import {resolveReportFields} from './report-fields.mjs';
export const reportLocation=r=>[r.edit.building,r.edit.floor?'Level '+r.edit.floor:'',r.edit.room?'Room '+r.edit.room:''].filter(Boolean).join(' · ')||'Location not entered';
export function displayDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return value||'Not recorded';const d=new Date(value+'T00:00:00Z');return Number.isNaN(d.valueOf())?value:new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(d);}
export function shortFindingTitle(row){const entered=(row.edit.shortTitle||'').trim();if(entered)return entered;const text=(row.edit.description||'Observation not entered').replace(/\s+/g,' ').trim();if(text.length<=90)return text;const cut=text.slice(0,87);return cut.slice(0,cut.lastIndexOf(' ')>50?cut.lastIndexOf(' '):87)+'…';}
export function reportInspectors(groups,override){return typeof override==='string'?override:[...new Set(groups.map(g=>g.inspector?.trim()).filter(Boolean))].join('; ');}
export function makeReport(data){
 const groups=data.groups.map((g,i)=>({...g,ref:'I'+String(i+1).padStart(2,'0')})),byId=new Map(groups.map(g=>[g.id,g]));
 const selectedFields=resolveReportFields(data),explicitReportFields=Array.isArray(data.reportFieldSelection),has=key=>selectedFields.includes(key);
 const showFindingDates=new Set(groups.map(g=>g.date||'')).size>1;
 const findings=data.rows.map((r,i)=>({...r,number:i+1,ref:'Finding '+String(i+1).padStart(2,'0'),bookmark:'finding_'+(i+1),selectedFields,explicitReportFields,includeRecommendedAction:has('recommendedAction'),responseRequested:has('departmentResponse'),showObservedOn:has('inspectionDate')&&(explicitReportFields||showFindingDates),location:reportLocation(r),shortTitle:shortFindingTitle(r),heading:'Finding '+String(i+1).padStart(2,'0')+((r.edit.shortTitle||'').trim()?' — '+r.edit.shortTitle.trim():''),inspectionRef:byId.get(r.inspection.id)?.ref||'Manual',photos:r.photos.filter(p=>p.include&&!p.removed&&p.variants[p.variant]).map((p,j,all)=>({...p,captionText:`Finding ${String(i+1).padStart(2,'0')} - Photo ${j+1} of ${all.length} (${p.variant==='report'?'edited for report':p.addedInReport?'added to report':p.variant})${p.caption?'\n'+p.caption:''}`}))}));
 const dates=groups.map(g=>g.date).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)).sort(),period=dates.length?displayDate(dates[0])+(dates[0]!==dates.at(-1)?' to '+displayDate(dates.at(-1)):''):'Not recorded';
 return {...data,inspectors:reportInspectors(groups,data.inspectors),selectedFields,explicitReportFields,includeRecommendedAction:has('recommendedAction'),departmentResponse:has('departmentResponse'),consolidated:data.findingsLayout==='consolidated',groups,findings,period,hasCategories:has('category')&&findings.some(r=>!!r.edit.category?.trim()),photoCount:findings.reduce((n,r)=>n+r.photos.length,0),coverPage:!!data.coverPage,includeContents:!!data.includeContents};
}
export function findingFields(f){const has=key=>!f.selectedFields||f.selectedFields.includes(key),blank='\n\n';return [...(has('location')?[['Location',f.location]]:[]),...(f.showObservedOn?[['Observed on',displayDate(f.inspection.date)]]:[]),['Observation',f.edit.description||'Observation not entered'],...(f.includeRecommendedAction!==false?[['Recommended corrective action',f.edit.action?.trim()?f.edit.action:blank]]:[]),...['category','priority','remarks'].filter(has).map(key=>[key[0].toUpperCase()+key.slice(1),f.edit[key]||(f.explicitReportFields?blank:'')]),...(f.responseRequested?[['Department response / action taken','\n\n\n']]:[])].filter(([,v])=>v);}
export function summaryTable(m,refs={}){const has=key=>m.selectedFields.includes(key),date=m.explicitReportFields&&has('inspectionDate');return {headers:['No',...(has('location')?['Location']:[]),...(date?['Observed on']:[]),'Finding',...(m.hasCategories?['Category']:[]),'Page'],weights:[.6,...(has('location')?[1.8]:[]),...(date?[1.3]:[]),5,...(m.hasCategories?[1.3]:[]),.7],rows:m.findings.map(f=>[String(f.number),...(has('location')?[f.location]:[]),...(date?[displayDate(f.inspection.date)]:[]),f.shortTitle,...(m.hasCategories?[f.edit.category||'-']:[]),String(refs[f.bookmark]||'')])};}
export function summaryRows(m,refs={}){return summaryTable(m,refs).rows;}
export function sourceFiles(m){return [...new Set(m.findings.flatMap(f=>f.sources))].map((name,i)=>['S'+String(i+1).padStart(2,'0'),name]);}
export function sourceRows(m){const files=new Map(sourceFiles(m).map(([ref,name])=>[name,ref]));return m.findings.map(f=>[String(f.number),`${f.inspectionRef} / ${f.original.reference||'Manual'}\n${f.original.id}${f.mergeSources?'\nMerged sources:\n'+f.mergeSources.map(s=>s.original.id+' · '+(s.original.reference||'')+' · '+s.inspection.title).join('\n'):''}`,f.photos.map(p=>`${p.reference||'Photo'}: ${p.id}${p.addedInReport?' (added to report)':''}${p.source?.originalName?'\nFilename: '+p.source.originalName:''}`).join('\n')+(sourceFiles(m).length>1&&f.sources.length?'\nFiles: '+f.sources.map(name=>files.get(name)).join(', '):'')]);}

export function consolidatedTable(m){
 const has=key=>m.selectedFields.includes(key);const columns=[{label:'No.',weight:.6,value:f=>String(f.number)},...(has('location')?[{label:'Location',weight:1.5,value:f=>f.location}]:[]),...(m.findings.some(f=>f.showObservedOn)?[{label:'Observed on',weight:1,value:f=>displayDate(f.inspection.date)}]:[]),{label:'Observation',weight:3,value:f=>((f.edit.shortTitle||'').trim()?f.edit.shortTitle.trim()+'\n':'')+(f.edit.description||'Observation not entered')},...(m.includeRecommendedAction!==false?[{label:'Recommended corrective action',weight:2.5,value:f=>f.edit.action||''}]:[]),...['category','priority','remarks'].filter(k=>has(k)&&(m.explicitReportFields||m.findings.some(f=>f.edit[k]?.trim()))).map(k=>({label:k[0].toUpperCase()+k.slice(1),weight:k==='remarks'?1.5:1,value:f=>f.edit[k]||''})),{label:'Photos',weight:1.2,value:f=>f.photos.length?f.photos.length+' photo'+(f.photos.length===1?'':'s')+' — '+f.ref+' in photo appendix':'None'},...(m.departmentResponse?[{label:'Department response / action taken',weight:2.2,value:()=>''}]:[])];
 return {headers:columns.map(c=>c.label),weights:columns.map(c=>c.weight),rows:m.findings.map(f=>columns.map(c=>c.value(f)))};
}
